#!/bin/zsh
cd "$(dirname "$0")"
D="$(pwd)/gen"
REF="$(pwd)/ref-style.png"
S="ESTILO OBLIGATORIO: exactamente el MISMO estilo de pixel art que los personajes de la imagen adjunta (pixel art de Pokémon Esmeralda de Game Boy Advance: píxeles grandes y nítidos, contorno oscuro de 1 píxel, sombreado por bloques, colores muy vivos y alegres en tonos pastel). Muebles vistos desde arriba en 3/4 como los interiores de Pokémon. NO dibujes los personajes de la referencia, solo copia el estilo. SIN texto, SIN letras, SIN números, SIN marcas de agua."
KEY="El FONDO debe ser magenta puro liso (#FF00FF) en toda la imagen, sin degradado ni sombras; cada objeto bien separado con mucho espacio magenta alrededor. No uses magenta dentro de los dibujos."
run(){ name=$1; shift; (codex exec -i "$REF" --dangerously-bypass-approvals-and-sandbox --skip-git-repo-check "Usa tu herramienta de generación de imágenes. $* Al final imprime NOMBRE => RUTA COMPLETA de cada imagen generada." < /dev/null > log24-$name.txt 2>&1; echo "DONE $name $?") & }
run g-bak1 "$S $KEY Crea g-bak1.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 8 objetos en 2 filas de 4, cada uno del mismo tamaño, en este orden (izquierda a derecha, fila por fila): 1) horno de ladrillo rojo con fuego encendido y leña abajo, 2) horno elegante dorado y crema con ventanita encendida, 3) mesa de trabajo de madera con un tazón y una batidora rosa encima y charolas abajo, 4) vitrina de vidrio para pasteles con marco de madera, VACÍA por dentro, 5) mostrador de madera con una caja registradora gris encima, 6) mesita redonda de café con dos sillas de madera, 7) planta verde en maceta blanca, 8) estante de madera con costales de harina y frascos."
run g-bak2 "$S $KEY Crea g-bak2.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 8 objetos en 2 filas de 4, cada uno del mismo tamaño, en este orden (izquierda a derecha, fila por fila): 1) batidora industrial plateada grande con tazón de metal, 2) máquina decoradora de pasteles con mangas de colores, 3) cafetera roja de espresso con tazas, 4) carrito de metal con charolas de panes y croissants, 5) horno moderno de acero con panes dorándose, 6) refrigerador rosa de pasteles con puertas de vidrio y pasteles adentro, 7) máquina de helados rosa con tres palancas y conos, 8) fuente de chocolate de tres pisos con fresas."
run g-bak3 "$S $KEY Crea g-bak3.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 8 objetos en 2 filas de 4, cada uno del mismo tamaño, en este orden (izquierda a derecha, fila por fila): 1) carrito de algodón de azúcar con toldo de rayas, 2) tapete redondo rosa con orilla de encaje (visto desde arriba), 3) cuadro enmarcado con un pastel de fresa, 4) reloj de pared redondo de madera, 5) lámpara colgante rosa con flecos, 6) ramo de globos de colores con moño, 7) ventana con cortinas rosas a cuadros, 8) pizarrón de menú tipo caballete, vacío."
run g-bak4 "$S $KEY Crea g-bak4.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 8 objetos en 2 filas de 4, cada uno del mismo tamaño, en este orden (izquierda a derecha, fila por fila): 1) florero blanco con flores rosas, 2) guirnalda horizontal de foquitos de colores con moños, 3) torre dorada de tres pisos con cupcakes, 4) repisa con frascos de dulces de colores, 5) oso de peluche gigante café con moño rosa, 6) fuentecita de piedra con flores, 7) candelabro dorado colgante con velitas, 8) letrero en forma de cupcake gigante con fresa."
run g-home1 "$S $KEY Crea g-home1.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 8 objetos en 2 filas de 4, cada uno del mismo tamaño, en este orden (izquierda a derecha, fila por fila): 1) cama individual rosa con almohada de corazón, 2) camita redonda para gato con cojín, 3) base de madera con un plato rosa con croquetas y un plato azul con agua, 4) tapete redondo rosa con flores (visto desde arriba), 5) ropero de madera blanco de dos puertas, 6) sofá rosa de dos plazas con cojines, 7) televisión sobre mueble de madera, 8) librero de madera con libros de colores."
run g-home2 "$S $KEY Crea g-home2.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 8 objetos en 2 filas de 4, cada uno del mismo tamaño, en este orden (izquierda a derecha, fila por fila): 1) escritorio blanco con lamparita y silla, 2) rascador de gato de dos pisos rosa, 3) pecera con pececitos sobre mueble, 4) piano de pared blanco, 5) baúl de juguetes abierto con peluches, 6) mesa de comedor redonda con dos sillas, 7) refrigerador menta pastel con imanes, 8) estufa blanca con horno y ollita."
run g-home3 "$S $KEY Crea g-home3.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 8 objetos en 2 filas de 4, cada uno del mismo tamaño, en este orden (izquierda a derecha, fila por fila): 1) mueble bajo de cocina con cubierta de mármol y alacena colgada arriba, 2) fregadero en mueble de cocina con alacena arriba, 3) estufa con horno integrado y campana arriba, 4) refrigerador alto menta de dos puertas, 5) isla de cocina con dos banquitos rosas, 6) mesa de comedor rectangular de mármol con cuatro sillas, 7) lámpara de pie con pantalla crema, 8) planta grande en maceta."
run g-home4 "$S $KEY Crea g-home4.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 8 objetos en 2 filas de 4, cada uno del mismo tamaño, en este orden (izquierda a derecha, fila por fila): 1) espejo de cuerpo completo con marco dorado, 2) puf redondo de colores, 3) casita de muñecas rosa, 4) tocador blanco con espejo redondo, 5) chimenea de ladrillo encendida, 6) estante con peluches, 7) cama de princesa rosa con dosel, 8) tapete rectangular azul con estrellas (visto desde arriba)."
run g-home5 "$S $KEY Crea g-home5.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 8 objetos en 2 filas de 4, cada uno del mismo tamaño, en este orden (izquierda a derecha, fila por fila): 1) alfombra rosa en forma de corazón (vista desde arriba), 2) cojín grande para el piso rosa, 3) buró blanco con lámpara, 4) columpio de interior colgado de un marco de madera, 5) tienda de campaña de juguete tipi con banderines, 6) consola de videojuegos con tele pequeña, 7) litera de madera azul y rosa, 8) sillón amarillo acolchonado."
run g-home6 "$S $KEY Crea g-home6.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 8 objetos en 2 filas de 4, cada uno del mismo tamaño, en este orden (izquierda a derecha, fila por fila): 1) mecedora de madera con cojín, 2) tortuguita en una pecerita redonda, 3) pajarito azul en jaula dorada, 4) caballito mecedor de madera, 5) mesita de té con tetera y tacitas, 6) pizarrón verde con marco de madera, 7) telescopio en tripié, 8) globo terráqueo en base de madera."
run g-home7 "$S $KEY Crea g-home7.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 8 objetos en 2 filas de 4, cada uno del mismo tamaño, en este orden (izquierda a derecha, fila por fila): 1) lámpara de lava morada, 2) alfombra arcoíris semicircular (vista desde arriba), 3) tocadiscos rosa retro, 4) trofeo dorado grande con pastel en la punta, 5) listón azul de primer lugar en atril, 6) tina blanca de patitas con burbujas y un patito, 7) lavabo blanco con espejo, 8) toallero con toallas rosa y azul."
run g-home8 "$S $KEY Crea g-home8.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 8 objetos en 2 filas de 4, cada uno del mismo tamaño, en este orden (izquierda a derecha, fila por fila): 1) patito de hule amarillo gigante, 2) tapete de baño celeste (visto desde arriba), 3) cesto de mimbre con ropa, 4) bolita de estambre rosa, 5) ratoncito de juguete gris, 6) túnel de tela para gatos morado (horizontal), 7) castillito de cartón para gatos, 8) maceta con flores."
wait
echo ALLDONE
